from collections import OrderedDict

from .clock import SystemClock
from .keys import canonical_key, check_namespace


class _Record:
    __slots__ = ("namespace", "value", "stored_at", "expires_at")

    def __init__(self, namespace, value, stored_at, expires_at):
        self.namespace = namespace
        self.value = value
        self.stored_at = stored_at
        self.expires_at = expires_at


class NamespacedCache:
    """Bounded LRU cache shared by several namespaces."""

    def __init__(self, capacity, ttl, clock=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if isinstance(ttl, bool) or not isinstance(ttl, (int, float)):
            raise TypeError("ttl must be a real number")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.capacity = capacity
        self.ttl = float(ttl)
        self._clock = SystemClock() if clock is None else clock
        self._store = OrderedDict()
        self._counters = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0,
            "puts": 0,
        }

    def _expired(self, record, now):
        return now > record.expires_at

    def put(self, namespace, key, value):
        canonical = canonical_key(namespace, key)
        now = self._clock.now()
        record = self._store.get(canonical)
        if record is not None:
            record.value = value
            record.stored_at = now
            record.expires_at = now + self.ttl
            self._store.move_to_end(canonical)
        else:
            if len(self._store) > self.capacity:
                self._store.popitem(last=False)
                self._counters["evictions"] += 1
            self._store[canonical] = _Record(namespace, value, now, now + self.ttl)
        self._counters["puts"] += 1
        return canonical

    def get(self, namespace, key, default=None):
        canonical = canonical_key(namespace, key)
        now = self._clock.now()
        record = self._store.get(canonical)
        if record is not None:
            if not self._expired(record, now):
                self._counters["hits"] += 1
                return record.value
            del self._store[canonical]
            self._counters["expirations"] += 1
        self._counters["misses"] += 1
        return default

    def delete(self, namespace, key):
        canonical = canonical_key(namespace, key)
        if canonical in self._store:
            del self._store[canonical]
            return True
        return False

    def clear(self, namespace=None):
        if namespace is None:
            removed = len(self._store)
            self._store.clear()
            return removed
        check_namespace(namespace)
        victims = [ck for ck, rec in self._store.items() if rec.namespace == namespace]
        for canonical in victims:
            del self._store[canonical]
        return len(victims)

    def purge_expired(self):
        now = self._clock.now()
        victims = [ck for ck, rec in self._store.items() if self._expired(rec, now)]
        for canonical in victims:
            del self._store[canonical]
        self._counters["expirations"] += len(victims)
        return len(victims)

    def keys(self, namespace=None):
        now = self._clock.now()
        result = []
        for canonical, record in reversed(self._store.items()):
            if self._expired(record, now):
                continue
            if namespace is not None and record.namespace != namespace:
                continue
            result.append(canonical)
        return result

    def namespaces(self):
        now = self._clock.now()
        return sorted({rec.namespace for rec in self._store.values()
                       if not self._expired(rec, now)})

    def __len__(self):
        now = self._clock.now()
        return sum(1 for rec in self._store.values() if not self._expired(rec, now))

    def stats(self):
        data = self._counters
        data["size"] = len(self)
        data["capacity"] = self.capacity
        return data

