"""Snapshot serialisation for nscache."""

from .clock import check_real

SNAPSHOT_VERSION = 2

_REQUIRED_FIELDS = ("version", "created_at", "capacity", "ttl", "stale_ttl", "entries")
_ENTRY_FIELDS = ("canonical", "namespace", "value", "stored_at", "expires_at")


def build_snapshot(created_at, capacity, ttl, stale_ttl, entries):
    """Build a fresh, detached snapshot mapping."""
    return {
        "version": SNAPSHOT_VERSION,
        "created_at": check_real(created_at, "created_at"),
        "capacity": capacity,
        "ttl": ttl,
        "stale_ttl": stale_ttl,
        "entries": [dict(entry) for entry in entries],
    }


def parse_snapshot(data):
    """Validate *data* and return a (created_at, records) pair."""
    if not isinstance(data, dict):
        raise TypeError("snapshot must be a dict")
    missing = [name for name in _REQUIRED_FIELDS if name not in data]
    if missing:
        raise ValueError("snapshot missing fields: " + ", ".join(sorted(missing)))
    version = data["version"]
    if (isinstance(version, bool) or not isinstance(version, int)
            or version != SNAPSHOT_VERSION):
        raise ValueError("unsupported snapshot version: %r" % (version,))
    created_at = check_real(data["created_at"], "created_at")
    entries = data["entries"]
    if not isinstance(entries, list):
        raise TypeError("snapshot entries must be a list")
    records = []
    for entry in entries:
        if not isinstance(entry, dict):
            raise TypeError("each snapshot entry must be a dict")
        absent = [name for name in _ENTRY_FIELDS if name not in entry]
        if absent:
            raise ValueError("snapshot entry missing fields: " + ", ".join(sorted(absent)))
        if not isinstance(entry["canonical"], str):
            raise TypeError("entry canonical must be a str")
        if not isinstance(entry["namespace"], str):
            raise TypeError("entry namespace must be a str")
        records.append({
            "canonical": entry["canonical"],
            "namespace": entry["namespace"],
            "value": entry["value"],
            "stored_at": check_real(entry["stored_at"], "stored_at"),
            "expires_at": check_real(entry["expires_at"], "expires_at"),
        })
    return created_at, records

