import re

_PATTERN = re.compile(r"\$\{(\w+)\}")


def interpolate(text, env):
    """Replace every ``${NAME}`` in ``text`` with ``env[NAME]``."""

    def _replace(match):
        name = match.group(1)
        if name in env:
            return str(env[name])
        return match.group(0)

    return _PATTERN.sub(_replace, text)


def interpolate_tree(value, env):
    """Interpolate the string values held by ``value``."""
    if isinstance(value, dict):
        return {
            key: interpolate(item, env) if isinstance(item, str) else item
            for key, item in value.items()
        }
    if isinstance(value, str):
        return interpolate(value, env)
    return value

