def deep_merge(base, overlay):
    """Merge ``overlay`` on top of ``base`` and return a new dict."""
    result = {}
    for key in sorted(set(base) | set(overlay)):
        if key in base and key in overlay:
            left = base[key]
            right = overlay[key]
            if isinstance(left, dict) and isinstance(right, dict):
                result[key] = deep_merge(left, right)
            else:
                result[key] = right
        elif key in base:
            result[key] = base[key]
        else:
            result[key] = overlay[key]
    return result


def walk(data, prefix=()):
    """Yield ``(path, value)`` pairs for the entries of ``data``."""
    for key, value in data.items():
        yield prefix + (key,), value

