from collections.abc import Mapping

from .errors import LayerError
from .interpolate import interpolate_tree
from .merge import deep_merge
from .sentinels import is_delete


class Config(Mapping):
    """View over a merged configuration."""

    def __init__(self, data, provenance):
        self._data = data
        self._provenance = provenance

    @property
    def data(self):
        return self._data

    @property
    def provenance(self):
        return self._provenance

    def source_of(self, *path):
        return self._provenance[path[0]]

    def __getitem__(self, key):
        return self._data[key]

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        return "Config(%r)" % (self._data,)


class ConfigLoader:
    """Accumulates named layers and merges them into a Config."""

    def __init__(self, env=None):
        self._env = env or {}
        self._layers = []

    @property
    def layer_names(self):
        return tuple(name for name, _ in self._layers)

    def add_layer(self, name, data):
        if not name:
            raise LayerError("layer name must be a non-empty string")
        self._layers.append((name, data))
        return self

    def build(self):
        merged = {}
        provenance = {}
        for name, raw in self._layers:
            layer = interpolate_tree(raw, self._env)
            for key, value in layer.items():
                if is_delete(value):
                    merged.pop(key, None)
                    provenance.pop(key, None)
                else:
                    merged = deep_merge(merged, {key: value})
                    provenance[key] = name
        return Config(merged, provenance)

