"""Environment interpolation with an explicit escape sequence."""

import string

from .errors import InterpolationError
from .sentinels import is_delete

_NAME_START = frozenset(string.ascii_letters + "_")
_NAME_CHARS = frozenset(string.ascii_letters + string.digits + "_")


def _valid_name(name):
    if not name or name[0] not in _NAME_START:
        return False
    return all(char in _NAME_CHARS for char in name)


def _resolve(body, env, text):
    name, sep, default = body.partition(":-")
    if not _valid_name(name):
        raise InterpolationError("invalid placeholder name %r in %r" % (name, text))
    if name in env:
        return str(env[name])
    if sep:
        return default
    raise InterpolationError("unresolved placeholder %r in %r" % (name, text))


def interpolate(text, env=None):
    """Expand ``${NAME}`` / ``${NAME:-default}`` placeholders in ``text``."""
    if not isinstance(text, str):
        raise InterpolationError(
            "interpolate() expects a string, got %s" % (type(text).__name__,)
        )
    env = {} if env is None else env
    out = []
    index = 0
    while index < len(text):
        char = text[index]
        if char != "$":
            out.append(char)
            index += 1
        elif text[index + 1:index + 2] == "$":
            out.append("$")
            index += 2
        elif text[index + 1:index + 2] == "{":
            end = text.find("}", index + 2)
            if end < 0:
                raise InterpolationError("unterminated placeholder in %r" % (text,))
            out.append(_resolve(text[index + 2:end], env, text))
            index = end + 1
        else:
            out.append("$")
            index += 1
    return "".join(out)


def interpolate_tree(value, env=None):
    """Recursively interpolate every string leaf of ``value``."""
    if is_delete(value):
        return value
    if isinstance(value, dict):
        return {key: interpolate_tree(item, env) for key, item in value.items()}
    if isinstance(value, list):
        return [interpolate_tree(item, env) for item in value]
    if isinstance(value, str):
        return interpolate(value, env)
    return value

