"""Order-preserving deep merge with deletion-sentinel support."""

import copy

from .sentinels import is_delete


def _prune(value):
    """Deep-copy ``value``, dropping every dict entry whose value is DELETE."""
    if isinstance(value, dict):
        return {
            key: _prune(item)
            for key, item in value.items()
            if not is_delete(item)
        }
    return copy.deepcopy(value)


def deep_merge(base, overlay):
    """Merge ``overlay`` on top of ``base`` and return a new independent dict."""
    if not isinstance(base, dict) or not isinstance(overlay, dict):
        raise TypeError("deep_merge() expects two dicts")
    result = _prune(base)
    for key, value in overlay.items():
        if is_delete(value):
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = _prune(value)
    return result


def _walk(data, prefix):
    for key, value in data.items():
        path = prefix + (key,)
        if isinstance(value, dict) and value:
            yield from _walk(value, path)
        else:
            yield path, value


def walk(data, prefix=()):
    """Return an iterator of ``(path, value)`` pairs for every leaf of ``data``."""
    if not isinstance(data, dict):
        raise TypeError("walk() expects a dict")
    return _walk(data, tuple(prefix))

