# --------------------------------------------------------------------------
# Independent oracles used by the randomized checks (no gold code imported).
# --------------------------------------------------------------------------
def oracle_copy(value):
    if isinstance(value, dict):
        return {key: oracle_copy(item) for key, item in value.items()}
    if isinstance(value, list):
        return [oracle_copy(item) for item in value]
    return value


def oracle_prune(value):
    if isinstance(value, dict):
        return {
            key: oracle_prune(item)
            for key, item in value.items()
            if item is not DELETE
        }
    return oracle_copy(value)


def oracle_merge(base, overlay):
    result = oracle_prune(base)
    for key, value in overlay.items():
        if value is DELETE:
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = oracle_merge(result[key], value)
        else:
            result[key] = oracle_prune(value)
    return result


def oracle_walk(data, prefix=()):
    for key, value in data.items():
        path = prefix + (key,)
        if isinstance(value, dict) and value:
            yield from oracle_walk(value, path)
        else:
            yield path, value


def oracle_build(layers):
    merged = {}
    provenance = {}
    for name, raw in layers:
        layer = oracle_copy(raw)
        merged = oracle_merge(merged, layer)
        layer_paths = {path for path, _ in oracle_walk(layer)}
        provenance = {
            path: (name if path in layer_paths else provenance.get(path, name))
            for path, _ in oracle_walk(merged)
        }
    return merged, provenance


def freeze(value):
    """Structural fingerprint capturing values AND key ordering."""
    if isinstance(value, dict):
        return ("dict", tuple((key, freeze(item)) for key, item in value.items()))
    if isinstance(value, list):
        return ("list", tuple(freeze(item) for item in value))
    if value is DELETE:
        return ("DELETE",)
    return ("scalar", repr(value))


def random_tree(rng, depth=0):
    keys = rng.sample(["a", "b", "c", "d", "e"], rng.randint(1, 4))
    out = {}
    for key in keys:
        roll = rng.random()
        if roll < 0.28 and depth < 2:
            out[key] = random_tree(rng, depth + 1)
        elif roll < 0.42:
            out[key] = DELETE
        elif roll < 0.60:
            out[key] = rng.randint(0, 99)
        elif roll < 0.74:
            out[key] = "v%d" % rng.randint(0, 9)
        elif roll < 0.84:
            out[key] = [rng.randint(0, 9), rng.randint(0, 9)]
        elif roll < 0.93:
            out[key] = rng.choice([True, False, None])
        else:
            out[key] = {}
    return out


