class InterpolationTests(unittest.TestCase):
    env = {"A": "alpha", "B": "beta", "EMPTY": "", "PORT": 5432, "_X1": "ok"}

    def test_basic_substitution(self):
        self.assertEqual(interpolate("${A}", self.env), "alpha")
        self.assertEqual(interpolate("x=${A};y=${B}", self.env), "x=alpha;y=beta")
        self.assertEqual(interpolate("${_X1}", self.env), "ok")

    def test_non_string_env_values_are_coerced(self):
        self.assertEqual(interpolate("${PORT}", self.env), "5432")

    def test_escape_sequence(self):
        self.assertEqual(interpolate("$${A}", self.env), "${A}")
        self.assertEqual(interpolate("$$", self.env), "$")
        self.assertEqual(interpolate("$$$$", self.env), "$$")
        self.assertEqual(interpolate("a$$b", self.env), "a$b")
        self.assertEqual(interpolate("$$${A}", self.env), "$alpha")

    def test_lone_dollar_is_literal(self):
        self.assertEqual(interpolate("cost: 5$", self.env), "cost: 5$")
        self.assertEqual(interpolate("$ {A}", self.env), "$ {A}")
        self.assertEqual(interpolate("$", self.env), "$")
        self.assertEqual(interpolate("$x", self.env), "$x")

    def test_defaults(self):
        self.assertEqual(interpolate("${NOPE:-fallback}", self.env), "fallback")
        self.assertEqual(interpolate("${NOPE:-}", self.env), "")
        self.assertEqual(interpolate("${A:-fallback}", self.env), "alpha")

    def test_present_but_empty_beats_default(self):
        self.assertEqual(interpolate("${EMPTY:-d}", self.env), "")
        self.assertEqual(interpolate("${EMPTY}", self.env), "")

    def test_default_is_literal_and_not_nested(self):
        self.assertEqual(interpolate("${NOPE:-${B}}", {}), "${B}")
        self.assertEqual(interpolate("${NOPE:-a:-b}", {}), "a:-b")
        self.assertEqual(interpolate("${NOPE:-$$}", {}), "$$")

    def test_unresolved_raises(self):
        with self.assertRaises(InterpolationError):
            interpolate("${NOPE}", self.env)
        with self.assertRaises(InterpolationError):
            interpolate("prefix ${NOPE} suffix", {})

    def test_unterminated_raises(self):
        with self.assertRaises(InterpolationError):
            interpolate("${A", self.env)
        with self.assertRaises(InterpolationError):
            interpolate("ok ${A:-x", self.env)

    def test_invalid_names_raise(self):
        for text in ("${}", "${1A}", "${A B}", "${-x}", "${:-d}", "${a-b}", "${a.b}"):
            with self.assertRaises(InterpolationError):
                interpolate(text, self.env)

    def test_non_string_input_raises(self):
        for bad in (5, None, ["${A}"], {"a": 1}):
            with self.assertRaises(InterpolationError):
                interpolate(bad, self.env)

    def test_env_defaults_to_empty(self):
        self.assertEqual(interpolate("plain"), "plain")
        self.assertEqual(interpolate("${A:-d}"), "d")
        self.assertEqual(interpolate(""), "")
        with self.assertRaises(InterpolationError):
            interpolate("${A}")

    def test_tree_recursion(self):
        src = {"a": {"b": ["${A}", 2, {"c": "${B}"}]}, "d": "${A}"}
        out = interpolate_tree(src, self.env)
        self.assertEqual(out, {"a": {"b": ["alpha", 2, {"c": "beta"}]}, "d": "alpha"})
        self.assertEqual(src["a"]["b"][0], "${A}")

    def test_tree_keeps_keys_and_scalars(self):
        out = interpolate_tree({"${A}": "${A}", "n": 3, "t": True, "z": None}, self.env)
        self.assertEqual(list(out), ["${A}", "n", "t", "z"])
        self.assertEqual(out["${A}"], "alpha")
        self.assertEqual(out["n"], 3)
        self.assertIs(out["t"], True)
        self.assertIsNone(out["z"])

    def test_tree_preserves_delete_identity(self):
        out = interpolate_tree({"a": DELETE, "b": [DELETE]}, self.env)
        self.assertIs(out["a"], DELETE)
        self.assertIs(out["b"][0], DELETE)
        self.assertIs(interpolate_tree(DELETE, self.env), DELETE)


