        if kind not in KINDS:
            raise OpError("unknown kind: %r" % (kind,))
        path = normalize_relpath(raw.get("path"))
        data = raw.get("data")
        expect = raw.get("expect")
        if kind == "delete" and data is not None:
            raise OpError("delete must not carry data: %s" % path)
        if kind in ("add", "update") and data is None:
            raise OpError("%s requires data: %s" % (kind, path))
        ops.append(Op(kind, path, data, expect))
    return tuple(ops)


def ordered(ops):
    """Return ops in the order they must be applied."""
    return tuple(sorted(ops, key=lambda op: (op.kind, op.path)))

