"""Content digests used for patch preconditions."""

import hashlib

ALGORITHM = "sha256"
_HEX = "0123456789abcdef"


def digest_bytes(data):
    """Return the canonical "sha256:<hex>" digest string for *data*."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError("digest_bytes() requires bytes, got %s" % type(data).__name__)
    return "%s:%s" % (ALGORITHM, hashlib.sha256(bytes(data)).hexdigest())


def content_digest(data):
    """Legacy helper returning the bare lowercase hex digest."""
    return digest_bytes(data).split(":", 1)[1]


def parse_digest(text):
    """Return (algorithm, lowercase hex) for a digest string."""
    if not isinstance(text, str):
        raise ValueError("digest must be a string, got %s" % type(text).__name__)
    if ":" in text:
        algo, _, hexpart = text.partition(":")
    else:
        algo, hexpart = ALGORITHM, text
    algo = algo.strip().lower()
    hexpart = hexpart.strip().lower()
    if algo != ALGORITHM:
        raise ValueError("unsupported digest algorithm: %r" % (algo,))
    if len(hexpart) != 64 or any(char not in _HEX for char in hexpart):
        raise ValueError("malformed digest: %r" % (text,))
    return algo, hexpart


def digests_equal(left, right):
    """Return True when two digest strings denote the same content."""
    try:
        return parse_digest(left) == parse_digest(right)
    except ValueError:
        return False

