"""Patch operation records and their canonical application order."""

from collections.abc import Mapping
from dataclasses import dataclass

from .digest import parse_digest
from .paths import normalize_relpath

KINDS = ("add", "update", "delete")
ORDER = {"delete": 0, "update": 1, "add": 2}
_FIELDS = frozenset({"kind", "path", "data", "expect"})


class OpError(ValueError):
    """Raised when a raw operation is malformed."""


@dataclass(frozen=True)
class Op:
    kind: str
    path: str
    data: bytes | None = None
    expect: str | None = None


def _as_mapping(raw):
    if isinstance(raw, Op):
        return {
            "kind": raw.kind,
            "path": raw.path,
            "data": raw.data,
            "expect": raw.expect,
        }
    if isinstance(raw, Mapping):
        return dict(raw)
    raise OpError("operation must be a mapping, got %s" % type(raw).__name__)


def parse_ops(raw_ops):
    """Validate raw operations and return a tuple of Op records."""
    ops = []
    seen = set()
    for raw in raw_ops:
        item = _as_mapping(raw)
        unknown = set(item) - _FIELDS
        if unknown:
            raise OpError("unknown keys: %s" % ", ".join(sorted(unknown)))
        kind = item.get("kind")
        if kind not in KINDS:
            raise OpError("unknown kind: %r" % (kind,))
        path = normalize_relpath(item.get("path"))
        data = item.get("data")
        expect = item.get("expect")
        if kind == "delete":
            if data is not None:
                raise OpError("delete must not carry data: %s" % path)
        elif isinstance(data, (bytes, bytearray, memoryview)):
            data = bytes(data)
        else:
            raise OpError("%s requires bytes data: %s" % (kind, path))
        if kind == "add" and expect is not None:
            raise OpError("add must not carry expect: %s" % path)
        if expect is not None:
            if not isinstance(expect, str):
                raise OpError("expect must be a string: %s" % path)
            try:
                parse_digest(expect)
            except ValueError as exc:
                raise OpError("bad expect for %s: %s" % (path, exc)) from exc
        if path in seen:
            raise OpError("duplicate path: %s" % path)
        seen.add(path)
        ops.append(Op(kind, path, data, expect))
    return tuple(ops)


def ordered(ops):
    """Return *ops* in canonical application order."""
    return tuple(sorted(ops, key=lambda op: (ORDER[op.kind], op.path)))

