"""Transactional application of patches to a directory tree."""

from dataclasses import dataclass
from pathlib import Path

from .digest import digest_bytes, digests_equal
from .ops import ordered, parse_ops
from .paths import resolve_within


class PatchError(Exception):
    """Base class for patch application failures."""


class PreconditionError(PatchError):
    """Raised before any write when the tree does not match expectations."""


class PatchFailed(PatchError):
    """Raised when an effect failed and the tree was rolled back."""

    def __init__(self, message, path=None, cause=None, rolled_back=True):
        super().__init__(message)
        self.path = path
        self.cause = cause
        self.rolled_back = rolled_back


@dataclass(frozen=True)
class PatchReport:
    applied: tuple
    digests: tuple
    bytes_written: int
    dry_run: bool

    def paths(self):
        """Return the touched paths in applied order."""
        return tuple(path for _, path in self.applied)

    def digest_map(self):
        """Return a fresh dict of path -> digest of written content."""
        return dict(self.digests)


def _write_bytes(path, data):
    with open(path, "wb") as handle:
        handle.write(data)


def _remove_file(path):
    Path(path).unlink()


def _missing_parents(path):
    missing = []
    parent = path.parent
    while not parent.exists():
        missing.append(parent)
        if parent.parent == parent:
            break
        parent = parent.parent
    return missing


def _undo(journal):
    for entry in reversed(journal):
        action, target = entry[0], entry[1]
        try:
            if action == "restore":
                _write_bytes(target, entry[2])
            elif action == "unlink":
                if target.is_file():
                    target.unlink()
            elif action == "rmdir":
                if target.is_dir():
                    target.rmdir()
        except OSError:
            pass


def apply_patch(root, raw_ops, *, dry_run=False, writer=None, remover=None):
    """Apply *raw_ops* under *root* atomically and return a PatchReport."""
    base = Path(root)
    write = _write_bytes if writer is None else writer
    remove = _remove_file if remover is None else remover
    ops = ordered(parse_ops(raw_ops))
    if not base.is_dir():
        raise PreconditionError("root is not a directory: %s" % (base,))

    originals = {}
    for op in ops:
        target = resolve_within(base, op.path)
        if op.kind == "add":
            if target.exists():
                raise PreconditionError("already exists: %s" % op.path)
            continue
        if not target.is_file():
            raise PreconditionError("not a regular file: %s" % op.path)
        current = target.read_bytes()
        if op.expect is not None and not digests_equal(digest_bytes(current), op.expect):
            raise PreconditionError("digest mismatch: %s" % op.path)
        originals[op.path] = current

    applied = tuple((op.kind, op.path) for op in ops)
    digests = tuple(
        sorted((op.path, digest_bytes(op.data)) for op in ops if op.kind != "delete")
    )
    if dry_run:
        return PatchReport(applied, digests, 0, True)

    journal = []
    written = 0
    for op in ops:
        target = resolve_within(base, op.path)
        try:
            if op.kind == "delete":
                journal.append(("restore", target, originals[op.path]))
                remove(target)
            else:
                for parent in reversed(_missing_parents(target)):
                    journal.append(("rmdir", parent))
                target.parent.mkdir(parents=True, exist_ok=True)
                if op.kind == "add":
                    journal.append(("unlink", target))
                else:
                    journal.append(("restore", target, originals[op.path]))
                write(target, op.data)
                written += len(op.data)
        except Exception as exc:
            _undo(journal)
            raise PatchFailed(
                "%s failed for %s: %s" % (op.kind, op.path, exc),
                path=op.path,
                cause=exc,
                rolled_back=True,
            ) from exc
    return PatchReport(applied, digests, written, False)


def apply_ops(root, raw_ops):
    """Legacy entry point returning the touched paths."""
    return list(apply_patch(root, raw_ops).paths())

